function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const STOP = { the: 1, and: 1, of: 1, a: 1, an: 1, by: 1, for: 1,
  ventures: 1, venture: 1, capital: 1, partners: 1, partner: 1, fund: 1, funds: 1,
  group: 1, llp: 1, pvt: 1, ltd: 1, private: 1, limited: 1, vc: 1, advisors: 1, india: 1 };
function toks(x) {
  const out = {};
  for (const w of s(x).toLowerCase().split(/[^a-z0-9]+/)) {
    if (w && w.length > 1 && !STOP[w]) { out[w] = 1; }
  }
  return Object.keys(out);
}
// exact, prefix, or every significant token of the shorter name present in the longer
function same(a, b) {
  const na = nz(a), nb = nz(b);
  if (!na || !nb) { return false; }
  if (na === nb) { return true; }
  if (na.length >= 6 && nb.length >= 6 && (na.indexOf(nb) === 0 || nb.indexOf(na) === 0)) { return true; }
  const ta = toks(a), tb = toks(b);
  if (!ta.length || !tb.length) { return false; }
  let hit = 0;
  for (const w of ta) { if (tb.indexOf(w) >= 0) { hit++; } }
  return hit > 0 && hit === Math.min(ta.length, tb.length);
}

// values API returns a raw grid; take the 'Firm name' column by header
function firmsFrom(resp, label) {
  const vals = (resp && resp.values) || [];
  if (!vals.length) { throw new Error('ABORT: ' + label + ' returned no rows'); }
  const hdr = vals[0].map(function (h) { return s(h).toLowerCase(); });
  let ci = -1;
  for (let i = 0; i < hdr.length; i++) { if (hdr[i].indexOf('firm') >= 0) { ci = i; break; } }
  if (ci < 0) { throw new Error('ABORT: no Firm name column in ' + label + ' -> ' + JSON.stringify(hdr)); }
  const out = [];
  for (let r = 1; r < vals.length; r++) { const n = s(vals[r][ci]); if (n) { out.push(n); } }
  return out;
}

const thesisFirms = firmsFrom($('GET Thesis correction').first().json, 'Thesis correction');
const mailFirms = firmsFrom($('GET Mail correction').first().json, 'Mail correction');
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

// one pass counted per investor+startup pair
const passed = {}, seen = {};
for (const p of pipe) {
  const resp = s(p.investor_response).toLowerCase();
  if (resp !== 'pass' && resp !== 'passed') { continue; }
  const invName = s(p.investor);
  if (!invName) { continue; }
  const key = nz(invName) + '|' + nz(p.startup);
  if (seen[key]) { continue; }
  seen[key] = 1;
  if (!passed[invName]) { passed[invName] = 0; }
  passed[invName]++;
}

const detail = [];
let withThesis = 0, withMail = 0, withAny = 0;
for (const name of Object.keys(passed)) {
  const mt = thesisFirms.filter(function (f) { return same(name, f); });
  const mm = mailFirms.filter(function (f) { return same(name, f); });
  if (mt.length) { withThesis++; }
  if (mm.length) { withMail++; }
  if (mt.length || mm.length) { withAny++; }
  detail.push({ investor: name, passed_deals: passed[name],
    thesis: mt.length ? mt[0] : '', mail: mm.length ? mm[0] : '',
    gave: (mt.length || mm.length) ? 'YES' : 'no' });
}
detail.sort(function (a, b) { return b.passed_deals - a.passed_deals || a.investor.localeCompare(b.investor); });

// corrections-sheet firms that never appear as a passing investor
const allPassNames = Object.keys(passed);
const orphanThesis = thesisFirms.filter(function (f) {
  return !allPassNames.some(function (n) { return same(n, f); }); });

const total = detail.length;
return [{ json: {
  unique_investors_who_passed: total,
  gave_any_correction: withAny,
  gave_thesis_correction: withThesis,
  gave_mail_correction: withMail,
  pct_any: total ? Math.round(withAny / total * 1000) / 10 : 0,
  thesis_tab_firms: thesisFirms.length,
  mail_tab_firms: mailFirms.length,
  corrections_from_non_passers: orphanThesis.length,
  detail: detail
} }];
